import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  const group = new Group();

  // Create an explicit backdrop plane for stage depth and structural grounding
  const backdropGeom = new PlaneGeometry(7.0, 6.0);
  const backdropMat = new MeshBasicNodeMaterial({
    color: '#0b0b10', // Spec Surface Color
    depthWrite: false
  });
  const backdrop = new Mesh(backdropGeom, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // Main interactive Card element (Engineered Surface)
  const cardGeom = new PlaneGeometry(4.0, 2.5);
  const cardMat = new MeshBasicNodeMaterial({
    color: '#16161d', // Spec Ink Color
    transparent: true,
    opacity: 0.95
  });
  const cardMesh = new Mesh(cardGeom, cardMat);
  group.add(cardMesh);

  // Load the product image if provided in config
  const imageUrl = config.imageUrl || (config.intent?.visualSpec?.imageUrl);
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      cardMat.color.set('#ffffff');
      cardMat.map = texture;
      cardMat.needsUpdate = true;
    }).catch((err) => {
      console.warn("Failed loading texture", err);
    });
  }

  // Subtle entrance animation following the "fade-up" styling paradigm
  gsap.fromTo(cardMesh.position, 
    { y: -0.4, x: 0 }, 
    { y: 0, x: 0, duration: 0.8, ease: 'power3.out' }
  );
  gsap.fromTo(cardMesh.scale,
    { x: 0.95, y: 0.95 },
    { x: 1, y: 1, duration: 0.8, ease: 'power3.out' }
  );

  // Setup the required cleanup protocol
  const cleanup = () => {
    gsap.killTweensOf(cardMesh.position);
    gsap.killTweensOf(cardMesh.scale);
    cardGeom.dispose();
    cardMat.dispose();
    backdropGeom.dispose();
    backdropMat.dispose();
  };

  group.userData = {
    handlers: {},
    cleanup
  };

  return group;
}
